        { q: "Apakah maksud pembiasan cahaya (refraction)?", qEn: "What is refraction of light?", options: ["Pembengkokan sinar cahaya apabila merambat secara serong dari satu medium ke medium berlainan ketumpatan optik", "Pantulan cahaya pada cermin rata", "Penyerapan cahaya oleh permukaan hitam", "Penyebaran cahaya putih"], optionsEn: ["Bending of light when passing obliquely between media of different optical densities", "Reflection off a flat mirror", "Absorption by a black surface", "Dispersion of white light"], correctIndex: 0, explanation: "Pembiasan berlaku kerana perubahan kelajuan cahaya dalam medium berbeza.", explanationEn: "Refraction occurs due to a change in light speed across media." },
        { q: "Apakah Hukum Snell bagi pembiasan cahaya?", qEn: "What is Snell's Law for refraction?", options: ["n = sin i / sin r", "n = sin r / sin i", "n = i + r", "n = c × v"], correctIndex: 0, explanation: "Indeks biasan n = sin i / sin r (dari udara/vakum ke medium).", explanationEn: "Refractive index n = sin i / sin r." },
        { q: "Bilakah pantulan dalam penuh (total internal reflection) boleh berlaku?", qEn: "When does total internal reflection occur?", options: ["Cahaya bergerak dari medium lebih tumpat ke kurang tumpat DAN sudut tuju melebihi sudut genting (i > c)", "Cahaya bergerak dari udara ke kaca", "Sudut tuju lebih kecil daripada sudut genting", "Pada cermin satah sahaja"], optionsEn: ["Light travels from denser to less dense medium AND angle of incidence > critical angle (i > c)", "Light travels from air to glass", "Angle of incidence < critical angle", "On plane mirrors only"], correctIndex: 0, explanation: "Dua syarat wajib: 1) Lebih tumpat -> kurang tumpat, 2) i > c.", explanationEn: "Requires denser-to-less-dense medium and i > critical angle c." },
        { q: "Apakah aplikasi pantulan dalam penuh dalam telekomunikasi moden?", qEn: "What is a major application of total internal reflection in modern telecom?", options: ["Kabel gentian optik (optical fibre) dan periskop berprisma", "Cermin sisi kereta", "Kanta pembesar", "Kamera lubang jarum"], optionsEn: ["Optical fibre cables and prism periscopes", "Car side mirrors", "Magnifying glasses", "Pinhole cameras"], correctIndex: 0, explanation: "Gentian optik menghantar isyarat cahaya berkelajuan tinggi melalui pantulan dalam penuh.", explanationEn: "Optical fibres transmit light signals via total internal reflection." },
        { q: "Apakah ciri imej yang terbentuk oleh cermin satah?", qEn: "What are the characteristics of an image formed by a plane mirror?", options: ["Maya, tegak, sama saiz dengan objek dan songsang sisi", "Nyata, songsang dan lebih besar", "Nyata, tegak dan lebih kecil", "Maya dan songsang"], optionsEn: ["Virtual, upright, same size, and laterally inverted", "Real, inverted, magnified", "Real, upright, diminished", "Virtual and inverted"], correctIndex: 0, explanation: "Cermin satah menghasilkan imej maya, tegak, sama saiz dan songsang sisi.", explanationEn: "Plane mirror images are virtual, upright, same size, and laterally inverted." },
        { q: "Kanta manakah yang digunakan sebagai kanta pembesar (apabila objek diletakkan kurang daripada panjang fokus u < f)?", qEn: "Which lens is used as a magnifying glass (when u < f)?", options: ["Kanta cembung (penumpu)", "Kanta cekung (pencapah)", "Cermin cembung", "Blok kaca rata"], optionsEn: ["Convex (converging) lens", "Concave (diverging) lens", "Convex mirror", "Flat glass block"], correctIndex: 0, explanation: "Kanta cembung dengan u < f menghasilkan imej maya, tegak dan dibesarkan.", explanationEn: "A convex lens with u < f produces a virtual, upright, magnified image." },
        { q: "Apakah jenis imej yang sentiasa dihasilkan oleh kanta cekung?", qEn: "What type of image is ALWAYS formed by a concave lens?", options: ["Maya, tegak dan lebih kecil (dikecilkan)", "Nyata dan dibesarkan", "Nyata dan songsang", "Maya dan dibesarkan"], optionsEn: ["Virtual, upright, and diminished", "Real and magnified", "Real and inverted", "Virtual and magnified"], correctIndex: 0, explanation: "Kanta cekung mencapahkan cahaya dan sentiasa membentuk imej maya, tegak dan dikecilkan.", explanationEn: "Concave lenses always form virtual, upright, diminished images." },
        { q: "Mengapakah kolam renang kelihatan lebih cetek daripada kedalaman sebenarnya?", qEn: "Why does a swimming pool appear shallower than its actual depth?", options: ["Disebabkan pembiasan cahaya dari air ke udara menjauhi garis normal", "Kerana pantulan dalam penuh", "Kerana air menyerap semua cahaya", "Kerana cermin di dasar kolam"], optionsEn: ["Due to refraction of light bending away from the normal from water to air", "Due to total internal reflection", "Water absorbs all light", "Mirrors at the bottom"], correctIndex: 0, explanation: "Indeks biasan n = Dalam nyata / Dalam ketara.", explanationEn: "Refraction from water to air creates an apparent depth shallower than real depth." },
        { q: "Apakah formula kanta nipis?", qEn: "What is the thin lens formula?", options: ["1/f = 1/u + 1/v", "f = u + v", "1/f = u - v", "f = u × v"], correctIndex: 0, explanation: "f = panjang fokus, u = jarak objek, v = jarak imej.", explanationEn: "1/f = 1/u + 1/v." },
        { q: "Apakah fenomena semula jadi yang terhasil daripada pantulan dalam penuh dan pembiasan cahaya matahari dalam titisan air hujan?", qEn: "What natural phenomenon results from refraction and total internal reflection in raindrops?", options: ["Pelangi", "Gerhana Bulan", "Aurora", "Bayu laut"], optionsEn: ["Rainbow", "Lunar eclipse", "Aurora", "Sea breeze"], correctIndex: 0, explanation: "Cahaya matahari dibiaskan, disebarkan kepada spektrum warna dan dipantulkan di dalam titisan hujan.", explanationEn: "Rainbows form via refraction, dispersion, and internal reflection in raindrops." }
